SELECT s.point_code AS point_code, s.score AS score, s.at AS at, (SELECT COUNT(*) FROM progress_score c WHERE c.learner = s.learner AND c.point_code = s.point_code) AS n, COALESCE((SELECT p.score FROM progress_score p WHERE p.learner = s.learner AND p.point_code = s.point_code AND p.id < s.id ORDER BY p.id DESC LIMIT 1), s.score) AS prev_score FROM progress_score s WHERE s.learner = :learner AND s.id = (SELECT MAX(m.id) FROM progress_score m WHERE m.learner = s.learner AND m.point_code = s.point_code) ORDER BY s.score ASC, s.point_code ASC
